+    }
+
+    if (level == LOG_LEVEL_ERROR) {
+        G_BREAKPOINT();
+        ws_assert_not_reached();
+    }
+}
+
+
+void ws_logv(enum ws_log_domain domain, enum ws_log_level level,
+                    const char *format, va_list ap)
+{
